const inp = $('Recibir Datos').first().json;
const cache = $('🔍 Cache Config').first().json;
const empresa = cache.empresa || {};
const waConfig = cache.waConfig || {};
const productos = cache.productos || [];

const leadRaw = $('📋 Buscar Lead').first().json;
const leadsArr = leadRaw?.data || [];
const leadG54 = leadsArr[0] || null;

const leadId = leadG54?.id ? String(leadG54.id) : null;
const esNuevo = !leadId;

// Lee datos del campo datos de G54 (siempre llega vacío — bug Walter)
let datosGuardados = leadG54?.datos || {};
const historialRaw = leadG54?.historial || '';

// ============================================================
// WORKAROUND: G64 no guarda el campo `datos`.
// Solución: SW03 embebe un snapshot [D:{...}] en el historial
// cada turno. SW02 lo lee aquí como fuente de verdad.
// Cuando Walter arregle datos en backend, este bloque sale.
// ============================================================

// 1. FALLBACK: leer snapshot [D:{...}] del historial solo para campos que G54 no tiene
const dLines = historialRaw.split('\n').filter(l => l.includes('Agente: [D:'));
if (dLines.length > 0) {
  const lastLine = dLines[dLines.length - 1];
  const dContent = lastLine.replace(/.*Agente:\s*\[D:/, '').replace(/\]$/, '');
  try {
    const snap = JSON.parse(dContent);
    // Solo rellenar campos vacíos — G54 datos tiene prioridad
    for (const [k, v] of Object.entries(snap)) {
      if (v !== null && v !== undefined && !datosGuardados.hasOwnProperty(k)) datosGuardados[k] = v;
    }
  } catch(e) {}
}

// 2. FALLBACK si no hay snapshot aún (primeros mensajes): extraer de texto
const textoActual = (inp.texto || '').toLowerCase();
const todoTexto = historialRaw.toLowerCase() + ' ' + textoActual;

if (!datosGuardados.nombre_cliente && historialRaw) {
  const nameRx = /Agente:\s*(?:Hola|Buenos días|Buenas tardes|Buenas noches)[,.]?\s+([A-ZÁÉÍÓÚÑ][a-záéíóúñ]{1,20})[,!.]/g;
  const nameHits = [...historialRaw.matchAll(nameRx)];
  if (nameHits.length > 0) datosGuardados.nombre_cliente = nameHits[nameHits.length - 1][1];
}

if (!datosGuardados.tipo_flujo) {
  const cotizKws = ['cotiz', 'presupuesto', 'quote', 'estimado'];
  if (cotizKws.some(k => todoTexto.includes(k))) {
    datosGuardados.tipo_flujo = 'cotizacion';
  } else {
    const consultaKws = ['consulta', 'pregunta', 'informacion', 'información', 'info '];
    if (consultaKws.some(k => todoTexto.includes(k))) datosGuardados.tipo_flujo = 'consulta';
  }
}

// Limpiar [D:{...}] del historial antes de pasarlo a la IA
const historial = historialRaw.split('\n')
  .filter(l => !l.includes('Agente: [D:'))
  .join('\n');

// ============================================================

const estado = leadG54?.estado || 'Nuevo';
const nombreGuardado = leadG54?.contact_name || datosGuardados.nombre_cliente || '';

const catalogoProductos = productos.map(p => {
  const nombre = p.name || '';
  const desc = p.description || '';
  return nombre ? `${nombre}: ${desc}` : '';
}).filter(l => l.length > 2).join('\n');

const emailVendedor = (empresa.emails || [])[0] || waConfig.WA_Email_Vendedor || 'risosadmi@gmail.com';
const followup24 = waConfig.WA_FollowUp_24h || '';
const followup72 = waConfig.WA_FollowUp_72h || '';

const kbRaw = $('📚 Buscar KB').first().json;
const kbRecords = kbRaw?.records || [];
const msgTexto = (inp.texto || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');

let kbContexto = '';
if (kbRecords.length > 0) {
  const scored = kbRecords.map(r => {
    const f = r.fields || {};
    const kwField = f['keywords'] || f['fld0yfZZ92Sn4azoR'] || '';
    const kws = kwField.toLowerCase().split(/[,\s]+/);
    const score = kws.filter(kw => kw.length > 2 && msgTexto.includes(kw)).length;
    const pregunta = f['fldoHtlrUwmkCCKwM'] || Object.values(f)[0] || '';
    const corta = f['fldmfEyHk7i3o24T5'] || f['respuesta_corta'] || '';
    return { score, pregunta, corta };
  }).filter(r => r.score > 0).sort((a,b) => b.score - a.score).slice(0,3);
  if (scored.length > 0) {
    kbContexto = '\n\nINFORMACIÓN VERIFICADA (usa SOLO estos datos):\n' +
      scored.map(r => `• ${r.pregunta}\n  → ${r.corta}`).join('\n');
  }
}

return [{json: {
  telefono: inp.telefono,
  texto: inp.texto,
  nombreContacto: inp.nombreContacto || nombreGuardado,
  leadId, estado, historial, esNuevo,
  datosRecolectados: datosGuardados,
  emailVendedor, followup24, followup72,
  catalogoProductos, kbContexto,
  empresa, waConfig, productos
}}];

